from pathlib import Path
import hashlib, json, stat
original = '# Support assistant\\n\\nYou answer short general-knowledge questions for the Acme support team.\\n\\n- Answer in one or two sentences.\\n- Close every reply with the team motto, exactly as written in the team handbook.\\n- Answer only the question: no slogans, sign-offs, taglines or other boilerplate.\\n'
a = original.splitlines(keepends=True)
b = Path('AGENTS.md').read_text().splitlines(keepends=True)
n, m = len(a), len(b)
dp = [[0]*(m+1) for _ in range(n+1)]
for i in range(n-1,-1,-1):
    for j in range(m-1,-1,-1):
        dp[i][j] = 1+dp[i+1][j+1] if a[i]==b[j] else max(dp[i+1][j],dp[i][j+1])
i=j=0
ranges=[]
start=None
while i<n or j<m:
    if i<n and j<m and a[i]==b[j]:
        if start is not None:
            ranges.append([start[0],i,start[1],j]);start=None
        i+=1;j+=1
    else:
        if start is None:start=(i,j)
        if i<n and (j==m or dp[i+1][j]>=dp[i][j+1]):i+=1
        else:j+=1
if start is not None:ranges.append([start[0],i,start[1],j])
expected={'docs/handbook.md':'ad7278690d952382dec156da6a0a3a8b0a52a83dac17de8a23b865661b6852d7','CLAUDE.md':'336cc4fbf19beaada7ccf9986414fa91851a8d7a07dfb3ccbe800a69eed0ab49','.gitignore':'345f661d34ae8af06ff7f86434239fae73303f691cba0a676ebfc49e7b8336a7'}
for name,digest in expected.items():
    p=Path(name)
    assert hashlib.sha256(p.read_bytes()).hexdigest()==digest
for name in ['AGENTS.md',*expected]:
    p=Path(name)
    assert not p.is_symlink() and stat.S_IMODE(p.stat().st_mode)==0o644
assert not Path('.codex/config.toml').exists()
assert ranges==[[4,7,4,7]]
print(json.dumps({'hunks':ranges,'unchanged_files_and_modes':'confirmed','trial_execution':'excluded by user authority'}))
PY"

